'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk6-bai25-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#52;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/53 个词语。学完5组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),53)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共53个词语，点击 ↗ 学习该词语',totalLearned()+'/53 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、7个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===52;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<52){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:12};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课53个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课53个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [4, 10, 12], "5": [1, 2, 38], "8": [1, 2, 38], "11": [1, 2, 38], "14": [4, 10, 12], "17": [4, 10, 12], "20": [4, 10, 12], "23": [1, 2, 38], "26": [1, 2, 38], "29": [1, 2, 38], "32": [1, 2, 38], "35": [1, 2, 38], "38": [4, 10, 12], "41": [1, 2, 38], "44": [1, 2, 38], "47": [1, 2, 38], "50": [1, 2, 38]};
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的53个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第25课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第25课学习进度','第25课 · 53个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 53</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第25课';$('ntc-bookmark').textContent=student?total+'/53 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第25课学习进度</div><div style="padding:0 10px">'+total+'/53 个已学词语'+meter(total,53)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
const AUDIO_INDEX={"服气":"data:audio/mpeg;base64,","看到他拿出充分的证据，大家终于服气不再坚持原来的看法。":"data:audio/mpeg;base64,","军队":"data:audio/mpeg;base64,","故事中的将领带领军队按照事先商量的计划向前推进。":"data:audio/mpeg;base64,","武器":"data:audio/mpeg;base64,","博物馆通过实物和图片介绍了古代武器的发展变化。":"data:audio/mpeg;base64,","当务之急":"data:audio/mpeg;base64,","对这个团队来说核实资料中的错误才是当前的当务之急。":"data:audio/mpeg;base64,","承办":"data:audio/mpeg;base64,","这次文化交流活动由当地的一所学校承办准备工作已经基本完成。":"data:audio/mpeg;base64,","委托":"data:audio/mpeg;base64,","她委托朋友帮忙领取材料并提前说明了需要注意的事项。":"data:audio/mpeg;base64,","即将":"data:audio/mpeg;base64,","会议即将开始工作人员正在检查最后几项准备工作。":"data:audio/mpeg;base64,","紧迫":"data:audio/mpeg;base64,","虽然时间紧迫，大家仍然认真核对资料没有省略必要的步骤。":"data:audio/mpeg;base64,","公务":"data:audio/mpeg;base64,","他因为办理公务需要前往外地因此提前安排好了工作。":"data:audio/mpeg;base64,","款待":"data:audio/mpeg;base64,","主人准备了当地的特色菜热情款待远道而来的客人。":"data:audio/mpeg;base64,","叮嘱":"data:audio/mpeg;base64,","出发之前，母亲反复叮嘱他路上注意安全到了以后及时联系。":"data:audio/mpeg;base64,","算数":"data:audio/mpeg;base64,","他一向说话算数答应别人的事情都会努力做到。":"data:audio/mpeg;base64,","逼迫":"data:audio/mpeg;base64,","讨论方案时，不能逼迫别人接受意见，而应该耐心说明自己的理由。":"data:audio/mpeg;base64,","吩咐":"data:audio/mpeg;base64,","负责人吩咐大家先核对名单再安排接待工作。":"data:audio/mpeg;base64,","下属":"data:audio/mpeg;base64,","这位主管愿意听取下属的意见也鼓励大家主动提出改进建议。":"data:audio/mpeg;base64,","充足":"data:audio/mpeg;base64,","这次出行大家准备充足遇到天气变化时也能够从容应对。":"data:audio/mpeg;base64,","拖延":"data:audio/mpeg;base64,","如果一直拖延任务，原本充足的时间也可能很快变得紧张。":"data:audio/mpeg;base64,","期限":"data:audio/mpeg;base64,","请在规定期限内提交申请材料以便工作人员及时处理。":"data:audio/mpeg;base64,","活该":"data:audio/mpeg;base64,","他故意破坏规则受到处罚以后旁人说这真是活该。":"data:audio/mpeg;base64,","探听":"data:audio/mpeg;base64,","为了了解事情的经过，他向几位知情者探听相关消息。":"data:audio/mpeg;base64,","汇报":"data:audio/mpeg;base64,","每到周末，团队成员都会汇报进展共同讨论遇到的问题。":"data:audio/mpeg;base64,","探望":"data:audio/mpeg;base64,","回到家乡后，她专程探望了曾经帮助过自己的老师。":"data:audio/mpeg;base64,","寒暄":"data:audio/mpeg;base64,","多年未见的朋友见面后先寒暄了几句便谈起了近来的生活。":"data:audio/mpeg;base64,","为难":"data:audio/mpeg;base64,","两项安排恰好发生冲突让负责协调的他感到十分为难。":"data:audio/mpeg;base64,","严密":"data:audio/mpeg;base64,","这次活动组织严密每一个环节都有明确的负责人。":"data:audio/mpeg;base64,","侧面":"data:audio/mpeg;base64,","从另一个侧面观察，我们也许能够发现先前没有注意到的问题。":"data:audio/mpeg;base64,","机密":"data:audio/mpeg;base64,","这些材料涉及重要机密工作人员按照规定妥善保管。":"data:audio/mpeg;base64,","保密":"data:audio/mpeg;base64,","在结果正式公布之前，相关人员需要严格保密不能随意向外透露。":"data:audio/mpeg;base64,","走漏":"data:audio/mpeg;base64,","为了避免走漏消息，负责人提醒大家不要在公开场合讨论细节。":"data:audio/mpeg;base64,","沉思":"data:audio/mpeg;base64,","听完对方的解释他陷入沉思久久没有作出回答。":"data:audio/mpeg;base64,","意图":"data:audio/mpeg;base64,","沟通时，清楚说明自己的意图有助于减少不必要的误会。":"data:audio/mpeg;base64,","私自":"data:audio/mpeg;base64,","没有得到允许，任何人都不能私自修改已经确认的记录。":"data:audio/mpeg;base64,","妥当":"data:audio/mpeg;base64,","等所有事情都安排妥当，大家才放心地离开准备第二天的活动。":"data:audio/mpeg;base64,","占领":"data:audio/mpeg;base64,","这段历史材料记载了军队占领城池以后当地发生的变化。":"data:audio/mpeg;base64,","封锁":"data:audio/mpeg;base64,","由于桥梁需要紧急检查，相关路段被暂时封锁车辆只能绕行。":"data:audio/mpeg;base64,","驻扎":"data:audio/mpeg;base64,","故事里这支队伍在河边驻扎下来等待下一步命令。":"data:audio/mpeg;base64,","指定":"data:audio/mpeg;base64,","请大家按时到达指定地点听从工作人员的引导依次进入会场。":"data:audio/mpeg;base64,","响亮":"data:audio/mpeg;base64,","他站起身来用响亮的声音回答了老师的问题。":"data:audio/mpeg;base64,","舱":"data:audio/mpeg;base64,","风浪逐渐加大船上的旅客回到舱内等待工作人员通知。":"data:audio/mpeg;base64,","嘱咐":"data:audio/mpeg;base64,","临走时，她再三嘱咐朋友别忘了按时给花浇水。":"data:audio/mpeg;base64,","茫茫":"data:audio/mpeg;base64,","清晨，江面上白雾茫茫远处船只的轮廓也变得模糊起来。":"data:audio/mpeg;base64,","调动":"data:audio/mpeg;base64,","好的课堂任务能够调动学生的积极性让更多人愿意参与讨论。":"data:audio/mpeg;base64,","一齐":"data:audio/mpeg;base64,","听到这个好消息，大家一齐鼓掌为团队取得的进步感到高兴。":"data:audio/mpeg;base64,","方位":"data:audio/mpeg;base64,","在陌生的地方行走，他先借助地图确定自己所在的方位。":"data:audio/mpeg;base64,","高涨":"data:audio/mpeg;base64,","活动开始以后，同学们的参与热情十分高涨纷纷提出自己的想法。":"data:audio/mpeg;base64,","凌晨":"data:audio/mpeg;base64,","经过一夜的行驶，列车在凌晨时分抵达了目的地。":"data:audio/mpeg;base64,","笼罩":"data:audio/mpeg;base64,","浓雾笼罩着整个山谷直到太阳升高，才逐渐散去。":"data:audio/mpeg;base64,","启程":"data:audio/mpeg;base64,","确认行李已经装好以后，队员们按时启程沿着原定路线出发。":"data:audio/mpeg;base64,","大致":"data:audio/mpeg;base64,","通过这次介绍，我们已经大致了解了这项工作的基本流程。":"data:audio/mpeg;base64,","圆满":"data:audio/mpeg;base64,","在大家的共同努力下，这次交流活动终于圆满结束。":"data:audio/mpeg;base64,","叹气":"data:audio/mpeg;base64,","看到计划又要推迟，他忍不住叹气，随后重新安排了时间。":"data:audio/mpeg;base64,","天才":"data:audio/mpeg;base64,","人们常称他为音乐天才，但熟悉他的人知道他也付出了大量的练习时间。":"data:audio/mpeg;base64,","高明":"data:audio/mpeg;base64,","这个办法看似简单实际上十分高明巧妙地化解了眼前的难题。":"data:audio/mpeg;base64,"};
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai25-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai25_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai25-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=53)||!p.memory)throw Error();if(!confirm('恢复第25课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<53;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<53&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第25课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

